// Domain tables (issue #7 §4). Money is integer cents; calendar dates are 'YYYY-MM-DD' strings.
// Better Auth owns `user`, `session`, `account`, `verification` (auth-schema.ts, generated by its CLI).
import { sql } from 'drizzle-orm';
import { boolean, check, date, index, integer, jsonb, pgTable, primaryKey, smallint, text, timestamp, uuid } from 'drizzle-orm/pg-core';

import { user } from './auth-schema';

export * from './auth-schema';

const ts = (name: string) => timestamp(name, { withTimezone: true });
const createdAt = () => ts('created_at').notNull().defaultNow();
const updatedAt = () => ts('updated_at').notNull().defaultNow().$onUpdate(() => new Date());

export const userDocuments = pgTable('user_documents', {
  id: uuid('id').primaryKey().defaultRandom(),
  userId: text('user_id').notNull().references(() => user.id, { onDelete: 'cascade' }),
  type: text('type').notNull(), // PASSPORT | NATIONAL_ID
  objectKey: text('object_key').notNull(),
  fileName: text('file_name').notNull(),
  mimeType: text('mime_type').notNull(),
  sizeBytes: integer('size_bytes').notNull(),
  uploadedAt: ts('uploaded_at').notNull().defaultNow(),
});

export const houses = pgTable('houses', {
  id: uuid('id').primaryKey().defaultRandom(),
  name: text('name').notNull(),
  address: text('address'),
  currency: text('currency').notNull().default('EUR'),
  splitMode: text('split_mode').notNull(),
  fixedContributionCents: integer('fixed_contribution_cents'),
  contributionDayOfMonth: integer('contribution_day_of_month'),
  showBalanceToRoommates: boolean('show_balance_to_roommates').notNull().default(true),
  // set null (not cascade) when the creator deletes their account: the house and its history outlive them
  createdBy: text('created_by').references(() => user.id, { onDelete: 'set null' }),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

/** `userId` is the account id, or `guest_<...>` for roommates without an account (so no FK to `user`). */
export const members = pgTable(
  'members',
  {
    houseId: uuid('house_id').notNull().references(() => houses.id, { onDelete: 'cascade' }),
    userId: text('user_id').notNull(),
    role: text('role').notNull(), // ADMIN | ROOMMATE
    status: text('status').notNull(), // ACTIVE | REMOVED
    joinedAt: ts('joined_at').notNull(),
    removedAt: ts('removed_at'),
    individualContributionCents: integer('individual_contribution_cents'),
    displayName: text('display_name'),
    email: text('email'),
    photoKey: text('photo_key'),
    inviteCode: text('invite_code'),
  },
  (t) => [
    primaryKey({ columns: [t.houseId, t.userId] }),
    index('members_user_idx').on(t.userId),
    check('members_role', sql`${t.role} in ('ADMIN','ROOMMATE')`),
    check('members_status', sql`${t.status} in ('ACTIVE','REMOVED')`),
    check('members_removed', sql`(${t.status} = 'ACTIVE') = (${t.removedAt} is null)`),
  ],
);

export const categories = pgTable('categories', {
  id: uuid('id').primaryKey().defaultRandom(),
  houseId: uuid('house_id').notNull().references(() => houses.id, { onDelete: 'cascade' }),
  name: text('name').notNull(),
  icon: text('icon'),
  color: text('color'),
  amountType: text('amount_type').notNull(),
  expectedAmountCents: integer('expected_amount_cents'),
  intervalUnit: text('interval_unit'),
  intervalCount: integer('interval_count'),
  anchorDate: date('anchor_date', { mode: 'string' }),
  isActive: boolean('is_active').notNull().default(true),
  sortOrder: integer('sort_order').notNull().default(0),
  notes: text('notes'),
  names: jsonb('names').$type<Record<string, string>>(), // optional per-language names, language -> name
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

export const bills = pgTable(
  'bills',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    houseId: uuid('house_id').notNull().references(() => houses.id, { onDelete: 'cascade' }),
    categoryId: uuid('category_id').notNull().references(() => categories.id),
    amountCents: integer('amount_cents').notNull(),
    chargeDate: date('charge_date', { mode: 'string' }),
    periodStartDate: date('period_start_date', { mode: 'string' }),
    periodEndDate: date('period_end_date', { mode: 'string' }),
    notes: text('notes'),
    ocrStatus: text('ocr_status').notNull().default('NONE'),
    ocrData: jsonb('ocr_data'),
    createdBy: text('created_by').references(() => user.id, { onDelete: 'set null' }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
    // chargeDate → periodEndDate → creation day (UTC); a generated column can never drift from its inputs.
    effectiveDate: date('effective_date', { mode: 'string' })
      .notNull()
      .generatedAlwaysAs(sql`coalesce(charge_date, period_end_date, (created_at at time zone 'UTC')::date)`),
  },
  (t) => [
    index('bills_house_effective_idx').on(t.houseId, t.effectiveDate.desc()),
    check('bills_amount', sql`${t.amountCents} between 1 and 9999999`),
    check('bills_notes', sql`char_length(${t.notes}) <= 1000`),
  ],
);

/** Replaces `files[]` and the legacy single-file fields. Max 5 per bill is enforced by the API. */
export const billFiles = pgTable(
  'bill_files',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    billId: uuid('bill_id').notNull().references(() => bills.id, { onDelete: 'cascade' }),
    objectKey: text('object_key').notNull(),
    fileName: text('file_name').notNull(),
    mimeType: text('mime_type').notNull(),
    sizeBytes: integer('size_bytes').notNull(),
    position: smallint('position').notNull().default(0),
  },
  (t) => [index('bill_files_bill_idx').on(t.billId), check('bill_files_size', sql`${t.sizeBytes} <= 10485760`)],
);

export const payments = pgTable(
  'payments',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    houseId: uuid('house_id').notNull().references(() => houses.id, { onDelete: 'cascade' }),
    memberId: text('member_id').notNull(),
    month: date('month', { mode: 'string' }).notNull(), // first day of the month
    amountCents: integer('amount_cents').notNull(),
    note: text('note'),
    paidAt: ts('paid_at').notNull().defaultNow(),
    recordedBy: text('recorded_by').notNull(),
  },
  (t) => [
    index('payments_house_month_idx').on(t.houseId, t.month),
    check('payments_amount', sql`${t.amountCents} > 0`),
    check('payments_month', sql`extract(day from ${t.month}) = 1`),
  ],
);

export const invites = pgTable('invites', {
  code: text('code').primaryKey(),
  houseId: uuid('house_id').notNull().references(() => houses.id, { onDelete: 'cascade' }),
  status: text('status').notNull(),
  expiresAt: ts('expires_at').notNull(),
  maxUses: integer('max_uses').notNull(),
  usedCount: integer('used_count').notNull().default(0),
  createdBy: text('created_by').notNull(),
  createdAt: createdAt(),
});
